;-----------------------------------------------------------------------------
; SetScreenTarget                                13C164  97 PC, low confidence
; Makes the screen the draw target again: copies the screen header
; (BackBufferWidth) to ScreenWidth
;-----------------------------------------------------------------------------
SetScreenTarget:
        LD mov, edx, edi
        LD mov, eax, esi
        mov esi, BackBufferWidth
        mov edi, ScreenWidth
        mov ecx, 0Dh
        rep movsd
        LD mov, edi, edx
        LD mov, esi, eax
        ret
        db 00h,00h
